  if (dir && bridge) {
    await bridge.fs.writeTextFile(joinProjectPath(dir, "design.md"), memoryMarkdown);
  } else if (typeof localStorage !== "undefined") {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(memoryDesign));
    } catch {
    }
  }
